+  for (let pid = 4_000_000; ; pid++) {
+    try { process.kill(pid, 0); } catch (e: any) { if (e.code === "ESRCH") return pid; }
+  }
+}
+
+function age(file: string, seconds: number): void {
+  const when = new Date(Date.now() - seconds * 1000);
+  fs.utimesSync(file, when, when);
